cssCode:
.mandala-loader {
  width: 100px; height: 100px;
  border: 4px dashed #d4af37;
  border-radius: 50%;
  position: relative;
  animation: spinMandala 6s linear infinite;
  display: flex; align-items: center; justify-content: center;
}
.mandala-loader::before {
  content: ""; position: absolute;
  width: 70px; height: 70px;
  border: 3px dotted #ffaa00; border-radius: 50%;
  animation: spinMandalaReverse 4s linear infinite;
}
.mandala-loader::after {
  content: ""; position: absolute;
  width: 40px; height: 40px;
  border: 2px solid #ffcc66; border-radius: 50%;
}
@keyframes spinMandala { 100% { transform: rotate(360deg); } }
@keyframes spinMandalaReverse { 100% { transform: rotate(-360deg); } }

